    view.innerHTML=`<section class="dashboard-head"><div><div class="eyebrow">FINANCE · COMMISSION PAYMENTS</div><h2>Commission Payments</h2><p>${isMD?'Review consolidated payout batches. Deselect any row that should remain pending, then approve the selected total.':'Prepare agent commission payments, submit selected rows for MD approval, and record payment after approval.'}</p></div><button class="btn btn-sm" id="commission-payment-refresh">Refresh</button></section><section id="payout-content"><div class="loading-state">Loading commission payments…</div></section>`;
