      const paidBatches=batches.filter(batch=>batch.paymentStatus==='paid');
      const preparable=eligible.filter(x=>x.policyReady),blocked=eligible.filter(x=>!x.policyReady);
      const eligibleRows=eligible.map(x=>{const uplift=x.socialMediaPayoutStatus==='active'&&Number(x.tierAgentDealSharePercent)===100;return `<tr><td><input type="checkbox" data-prepare-line value="${safe(x.creditLineId)}" ${x.policyReady?'checked':'disabled'}></td><td><b>${safe(x.agentName)}</b><small>Tier earned by ${safe(x.tierAgentName)} · ${Number(x.tierAgentDealSharePercent).toFixed(2)}% executing share</small><small>Social-media ${uplift?'uplift eligible':x.socialMediaPayoutStatus==='active'?'Active, but no uplift because executing share is below 100%':'Inactive'}</small></td><td><b>${safe(x.opportunityReference)}</b><small>Deal ${safe(x.dealReference)}</small></td><td>${amount(x.confirmedActualReceived,x.currency)}</td><td>${x.totalCreditPercent}%</td><td>${safe(String(x.receiptDate).slice(0,10))}</td><td>${x.policyReady?'Ready':'Blocked — no active policy for receipt date'}</td></tr>`;}).join('');
      const trueUp=p=>p.triggerMethod==='quarter_achieved_rate'?Math.max(0,Number(p.agentPayoutAmount)-Number(p.currentCreditedAmount)*Number(p.bands?.[0]?.agentPercent||0)/100):0;
