      const calculationGroups=new Map();for(const payout of payouts){const key=`${payout.agentId}|${payout.quarterKey}|${payout.currency}`;if(!calculationGroups.has(key))calculationGroups.set(key,[]);calculationGroups.get(key).push(payout);}
      const calculationRegisterGroups=[...calculationGroups.values()].sort((a,b)=>String(a[0]?.agentName).localeCompare(String(b[0]?.agentName))||String(b[0]?.quarterKey).localeCompare(String(a[0]?.quarterKey))).map(group=>{const {rows,summary}=buildPayoutStatement(group),first=rows[0],documentUrl=`/api/finance/agent-payouts/${encodeURIComponent(first.agentId)}/quarters/${encodeURIComponent(first.quarterKey)}/document`,body=rows.map(row=>{const tranche=receiptTranche(row);return `<tr><td>${safe(payoutMonth(row.receiptDate))}</td><td>${safe(row.propertySold||'—')}</td><td><b>${safe(row.opportunityReference)}</b><small>Deal ${safe(row.dealReference)}</small></td><td>${amount(row.salePrice,row.currency)}</td><td>${row.dealGrossCommissionExVat==null?'—':amount(row.dealGrossCommissionExVat,row.currency)}</td><td>${amount(row.grossCommissionReceivedExVat??row.currentGrossCommissionAmount??row.currentCreditedAmount,row.currency)}</td><td>${tranche.percent==null?'—':`<b>${tranche.percent.toFixed(2)}%</b>`}<small>${safe(tranche.status)}</small></td><td>${amount(row.resultingGrossCommissionAmount??row.resultingCumulativeAmount,row.currency)}</td><td>${row.tierChanged?`<b>${row.achievedRate.toFixed(2)}%</b>`:`${row.achievedRate.toFixed(2)}%`}</td><td>${row.dealSplit<100?'Yes':'No'}</td><td>${row.dealSplit.toFixed(2)}%</td><td>${(row.achievedRate*row.dealSplit/100).toFixed(2)}%</td><td>${amount(row.commissionAmount,row.currency)}</td><td>${row.tierAdjustment>0?`<b>${amount(row.tierAdjustment,row.currency)}</b>`:amount(0,row.currency)}</td><td><b>${amount(row.totalCommission,row.currency)}</b></td><td>${amount(row.alreadyPaid,row.currency)}</td></tr>`;}).join('');return `<article class="mapping-version-card"><div class="panel-head"><div><h4>${safe(first.agentName)} · ${safe(first.quarterKey)}</h4><p>The crossing Deal's higher tier is bold. Any Tier Adjustment is shown against the earlier Deal being adjusted.</p></div><div class="admin-toolbar"><a class="btn btn-sm" href="${documentUrl}" target="_blank" rel="noopener">Print / view NYSA PDF</a><a class="btn btn-sm" href="${documentUrl}?download=1">Download email attachment</a></div></div><div class="pipeline-table-wrap"><table class="commission-payment-table payout-calculation-register"><thead><tr><th>Month</th><th>Unit particulars / Project</th><th>Internal ref no</th><th>Sale Price</th><th>Total Deal Commission — Excluding VAT</th><th>Company Gross Commission Received — Excluding VAT</th><th>Commission Received in This Tranche (%)</th><th>Cumulative Commission</th><th>Agent Share (%)</th><th>Split required</th><th>Split %</th><th>Commission after split (%)</th><th>Commission Amount</th><th>Tier Adjustment</th><th>Total Commission</th><th>Already Paid</th></tr></thead><tbody>${body}</tbody></table></div><div class="payout-summary-grid"><div><small>Total Commission Earned</small><b>${amount(summary.totalCommissionEarned,first.currency)}</b></div><div><small>Already Paid</small><b>${amount(summary.alreadyPaid,first.currency)}</b></div><div><small>Tier Adjustment</small><b>${amount(summary.tierAdjustmentDue,first.currency)}</b></div><div><small>To be Paid</small><b>${amount(summary.toBePaid,first.currency)}</b></div><div><small>Status</small><b>${safe(summary.status)}</b></div></div></article>`;}).join('');
